        return summed;
    }

    pub fn softmax(self: *Tensor, axis: usize) !void {
        if (axis >= self.shape.dims.len) return Error.InvalidAxis;
        try self.ensureWritable();
        const ndim = self.shape.dims.len;
        var reduced_dims = try self.allocator.alloc(usize, if (ndim > 1) ndim - 1 else 0);
        defer self.allocator.free(reduced_dims);
        var jj: usize = 0;
        var ii: usize = 0;
        while (ii < ndim) : (ii += 1) {
            if (ii != axis) {
                if (jj < reduced_dims.len) reduced_dims[jj] = self.shape.dims[ii];
                jj += 1;
            }
        }
        var reduced_size: usize = 1;
        for (reduced_dims) |d| reduced_size *= d;
        var indices = try self.allocator.alloc(usize, ndim);
        defer self.allocator.free(indices);
        var reduced_indices = try self.allocator.alloc(usize, reduced_dims.len);
        defer self.allocator.free(reduced_indices);
        var axis_vals = try self.allocator.alloc(f32, self.shape.dims[axis]);
        defer self.allocator.free(axis_vals);
        var ri: usize = 0;
        while (ri < reduced_size) : (ri += 1) {
            var rem = ri;
            if (reduced_dims.len > 0) {
                var dd = reduced_dims.len;
                while (dd > 0) {
                    dd -= 1;
                    reduced_indices[dd] = rem % reduced_dims[dd];
                    rem /= reduced_dims[dd];
                }
            }
            var ki: usize = 0;
            ii = 0;
            while (ii < ndim) : (ii += 1) {
                if (ii == axis) {
                    indices[ii] = 0;
                } else {
                    indices[ii] = if (reduced_dims.len > 0) reduced_indices[ki] else 0;
                    ki += 1;
                }
            }
            var max_val: f32 = -math.inf(f32);
            var k: usize = 0;
            while (k < self.shape.dims[axis]) : (k += 1) {
                indices[axis] = k;
                const idx = try self.computeIndex(indices);
                axis_vals[k] = self.data[idx];
                if (axis_vals[k] > max_val) max_val = axis_vals[k];
            }
            var sum_exp: f32 = 0.0;
            k = 0;
            while (k < self.shape.dims[axis]) : (k += 1) {
                axis_vals[k] = @exp(axis_vals[k] - max_val);
                sum_exp += axis_vals[k];
            }
            if (sum_exp < 1e-10) sum_exp = 1e-10;
            k = 0;
            while (k < self.shape.dims[axis]) : (k += 1) {
                indices[axis] = k;
                const idx = try self.computeIndex(indices);
                self.data[idx] = axis_vals[k] / sum_exp;
            }
        }
    }

    pub fn broadcast(self: *const Tensor, allocator: Allocator, target_shape: []const usize) !Tensor {
        var target_sh = try Shape.init(allocator, target_shape);
        defer target_sh.deinit(allocator);
        if (!self.shape.broadcastCompatible(&target_sh)) return Error.ShapeMismatch;
        var result = try init(allocator, target_shape);
        errdefer result.deinit();
        var target_indices = try allocator.alloc(usize, target_shape.len);
        defer allocator.free(target_indices);
        @memset(target_indices, 0);
        const offset = target_shape.len - self.shape.dims.len;
        var flat_idx: usize = 0;
        while (flat_idx < result.data.len) : (flat_idx += 1) {
            var src_idx: usize = 0;
            var i: usize = 0;
            while (i < self.shape.dims.len) : (i += 1) {
                const target_i = target_indices[offset + i];
                const src_i = if (self.shape.dims[i] == 1) 0 else target_i;
                src_idx += src_i * self.shape.strides[i];
            }
            result.data[flat_idx] = self.data[src_idx];
            var carry = true;
            var dim = target_shape.len;
            while (carry and dim > 0) {
                dim -= 1;
                target_indices[dim] += 1;
                if (target_indices[dim] < target_shape[dim]) {
                    carry = false;
                } else {
                    target_indices[dim] = 0;
                }
            }
        }
        return result;
    }

    pub fn unsqueeze(self: *const Tensor, allocator: Allocator, axis: usize) !Tensor {
        if (axis > self.shape.dims.len) return Error.InvalidAxis;
        var new_dims = try allocator.alloc(usize, self.shape.dims.len + 1);
        defer allocator.free(new_dims);
        var jj: usize = 0;
        var ii: usize = 0;
        while (ii < self.shape.dims.len + 1) : (ii += 1) {
            if (ii == axis) {
                new_dims[ii] = 1;
            } else {
                new_dims[ii] = self.shape.dims[jj];
                jj += 1;
            }
        }
        var result = try init(allocator, new_dims);
        errdefer result.deinit();
        const total = try self.shape.totalSize();
        if (self.shape.isContiguous()) {
            @memcpy(result.data[0..total], self.data[0..total]);
        } else {
            var indices = try allocator.alloc(usize, self.shape.dims.len);
            defer allocator.free(indices);
            @memset(indices, 0);
            var idx: usize = 0;
            while (idx < total) : (idx += 1) {
                var src: usize = 0;
                var si: usize = 0;
                while (si < self.shape.dims.len) : (si += 1) {
                    src += indices[si] * self.shape.strides[si];
                }
                result.data[idx] = self.data[src];
                var carry = true;
                var d = self.shape.dims.len;
                while (carry and d > 0) {
                    d -= 1;
                    indices[d] += 1;
                    if (indices[d] < self.shape.dims[d]) {
                        carry = false;
                    } else {
                        indices[d] = 0;
                    }
                }
            }
        }
        return result;
    }

    pub fn pad(self: *const Tensor, allocator: Allocator, pads: []const [2]usize) !Tensor {
        if (pads.len != self.shape.dims.len) return Error.InvalidPads;
        var new_shape = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.shape.dims.len) : (i += 1) {
            new_shape[i] = self.shape.dims[i] + pads[i][0] + pads[i][1];
        }
        var new_t = try init(allocator, new_shape);
        errdefer new_t.deinit();
        var indices = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var src_indices = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(src_indices);
        while (true) {
            var is_pad = false;
            i = 0;
            while (i < self.shape.dims.len) : (i += 1) {
                if (indices[i] < pads[i][0] or indices[i] >= pads[i][0] + self.shape.dims[i]) {
                    is_pad = true;
                } else {
                    src_indices[i] = indices[i] - pads[i][0];
                }
            }
            if (!is_pad) {
                const val = try self.get(src_indices);
                try new_t.set(indices, val);
            }
            var carry = true;
            var dim = self.shape.dims.len;
            while (carry and dim > 0) {
                dim -= 1;
                indices[dim] += 1;
                if (indices[dim] < new_shape[dim]) {
                    carry = false;
                } else {
                    indices[dim] = 0;
                }
            }
            if (carry) break;
        }
        return new_t;
    }

    pub fn tile(self: *const Tensor, allocator: Allocator, reps: []const usize) !Tensor {
        if (reps.len != self.shape.dims.len) return Error.InvalidReps;
        var new_shape = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(new_shape);
        var i: usize = 0;
        while (i < self.shape.dims.len) : (i += 1) {
            new_shape[i] = self.shape.dims[i] * reps[i];
        }
        var new_t = try init(allocator, new_shape);
        errdefer new_t.deinit();
        var indices = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(indices);
        @memset(indices, 0);
        var src_indices = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(src_indices);
        while (true) {
            i = 0;
            while (i < self.shape.dims.len) : (i += 1) {
                src_indices[i] = indices[i] % self.shape.dims[i];
            }
            const val = try self.get(src_indices);
            try new_t.set(indices, val);
            var carry = true;
            var dim = self.shape.dims.len;
            while (carry and dim > 0) {
                dim -= 1;
                indices[dim] += 1;
                if (indices[dim] < new_shape[dim]) {
                    carry = false;
                } else {
                    indices[dim] = 0;
                }
            }
            if (carry) break;
        }
        return new_t;
    }

    pub fn concat(allocator: Allocator, tensors: []const Tensor, axis: usize) !Tensor {
